   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="白蔷薇气急败坏地连开数枪，可光束也只是穿过了虚无的黑雾。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_703.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
